`timescale 1ns / 1ps
//=============================================================================
// note_rom.v : MIDI note -> 24-bit DDS phase increment
//-----------------------------------------------------------------------------
// Owner   : Student A
// Purpose : The table is DATA generated by tools/gen_note_table.py
//           (inc = round(f * 2^24 / 48828.125)). Notes 36..96 are stored at
//           address note-36; anything outside that range plays silence.
//           64 x 24 bits is small enough for distributed (LUT) ROM, which
//           reads combinationally.
//=============================================================================
module note_rom #(
    parameter MEM_FILE = "note_inc.mem"
) (
    input  wire [6:0]  note,
    output wire [23:0] inc
);
    reg [23:0] rom [0:63];
    initial $readmemh(MEM_FILE, rom);

    wire [6:0] addr = note - 7'd36;
    wire       in_range = (note >= 7'd36) && (note <= 7'd96);
    assign inc = in_range ? rom[addr[5:0]] : 24'd0;
endmodule
